-- Template Objective (SOAP) per diagnosa, dari file Excel "Template Objective Kaffah 329 Diagnosa".
-- Sintaks sama dengan Subjective, ditambah: (+/-) positif/negatif, (.....)/10 skala klik,
-- [ ... ] kelompok opsional, | pemisah item, {{form:barthel}} pop-up formulir fungsional.

alter table public.operational_options
  add column if not exists objective_template text;

comment on column public.operational_options.objective_template is
  'Template teks Objective SOAP untuk diagnosa (category = diagnosa). Format: **Judul:** isi, satu bagian per baris.';

