update public.operational_options o
   set objective_template = b.body
  from b
 cross join lateral unnest(b.names) as n(name)
 where o.category = 'diagnosa'
   and lower(btrim(o.label)) = lower(btrim(n.name))
   and o.objective_template is distinct from b.body;

